public IDisposable Enter (string key)
{
    Locker locker;
    lock (this.globalLock)
    {
        if (this.locks.ContainsKey (key))
        {
            locker = this.locks [key];
        }
        else
        {
            locker = new Locker (this, key);
            this.locks [key] = locker;
        }
        locker.WaitCount ++;
    }
    locker.Enter ();
    locker.WaitCount --;
    return locker;
}

